import { Geolocation as ApiGeolocation } from "@api/api-types.ts";

export interface ColdStartPosition {
  latitude: number;
  longitude: number;
  apiGeolocation: ApiGeolocation;
  country: string;
}

export interface RefreshColdStartGeolocationOptions {
  getCachedPosition: () => Promise<ColdStartPosition | null>;
  setPosition: (position: ColdStartPosition) => void;
  isAndroid: boolean;
  requestAndroidLocationPermission: () => Promise<boolean>;
  getCurrentCoordinates: () => Promise<{
    latitude: number;
    longitude: number;
  }>;
  fetchCountryGeolocation: (
    latlng: string,
  ) => Promise<ApiGeolocation | null | undefined>;
  isAvailableCountry: (country: string) => boolean;
  savePosition: (position: ColdStartPosition) => Promise<void>;
}

const countryLongName = (
  response: ApiGeolocation | null | undefined,
): string | undefined => {
  const longName = response?.results?.[0]?.address_components?.[0]?.long_name;
  if (typeof longName !== "string" || longName.length === 0) {
    return undefined;
  }
  return longName;
};

export const refreshColdStartGeolocation = async (
  options: RefreshColdStartGeolocationOptions,
): Promise<void> => {
  const cachedPosition = await options.getCachedPosition();
  if (cachedPosition) {
    options.setPosition(cachedPosition);
  }

  if (options.isAndroid) {
    const granted = await options.requestAndroidLocationPermission();
    if (!granted) {
      return;
    }
  }

  let coordinates: { latitude: number; longitude: number };
  try {
    coordinates = await options.getCurrentCoordinates();
  } catch {
    return;
  }

  try {
    const response = await options.fetchCountryGeolocation(
      `${coordinates.latitude},${coordinates.longitude}`,
    );
    const countryName = countryLongName(response);
    if (!response || !countryName || !options.isAvailableCountry(countryName)) {
      return;
    }
    const nextPosition: ColdStartPosition = {
      latitude: coordinates.latitude,
      longitude: coordinates.longitude,
      apiGeolocation: response,
      country: countryName,
    };
    options.setPosition(nextPosition);
    await options.savePosition(nextPosition);
  } catch {
    return;
  }
};

