import { Geolocation } from '../src/api/api-types';
import { FAKE_GEOLOCATION_RESPONSE } from '../src/constants/fake-geolocation';
import {
  ColdStartPosition,
  refreshColdStartGeolocation,
} from '../src/store/refresh-cold-start-geolocation';

const hongKongResponse: Geolocation = {
  ...FAKE_GEOLOCATION_RESPONSE,
  results: [
    {
      ...FAKE_GEOLOCATION_RESPONSE.results[0],
      address_components: [
        {
          ...FAKE_GEOLOCATION_RESPONSE.results[0].address_components[0],
          long_name: 'Hong Kong',
          short_name: 'HK',
        },
      ],
      formatted_address: 'Hong Kong',
    },
  ],
};

const cachedHongKong: ColdStartPosition = {
  latitude: 22.3193,
  longitude: 114.1694,
  apiGeolocation: hongKongResponse,
  country: 'Hong Kong',
};

const availableCountries = new Set(['Hong Kong', 'China', 'Singapore']);

const createOptions = (
  overrides: Partial<Parameters<typeof refreshColdStartGeolocation>[0]> = {},
) => {
  const setPosition = jest.fn();
  const savePosition = jest.fn(async () => undefined);
  const requestAndroidLocationPermission = jest.fn(async () => true);
  const getCurrentCoordinates = jest.fn(async () => ({
    latitude: 31.2304,
    longitude: 121.4737,
  }));
  const fetchCountryGeolocation = jest.fn(async () => FAKE_GEOLOCATION_RESPONSE);

  return {
    setPosition,
    savePosition,
    requestAndroidLocationPermission,
    getCurrentCoordinates,
    fetchCountryGeolocation,
    options: {
      getCachedPosition: async () => cachedHongKong,
      setPosition,
      isAndroid: true,
      requestAndroidLocationPermission,
      getCurrentCoordinates,
      fetchCountryGeolocation,
      isAvailableCountry: (country: string) => availableCountries.has(country),
      savePosition,
      ...overrides,
    },
  };
};

describe('refreshColdStartGeolocation', () => {
  test('requests geolocation on cold start even when a country is already cached', async () => {
    const { options, setPosition, savePosition, fetchCountryGeolocation } =
      createOptions();

    await refreshColdStartGeolocation(options);

    expect(fetchCountryGeolocation).toHaveBeenCalledTimes(1);
    expect(fetchCountryGeolocation).toHaveBeenCalledWith('31.2304,121.4737');
    expect(setPosition).toHaveBeenNthCalledWith(1, cachedHongKong);
    expect(savePosition).toHaveBeenCalledTimes(1);
    expect(savePosition).toHaveBeenCalledWith(
      expect.objectContaining({
        latitude: 31.2304,
        longitude: 121.4737,
        country: 'China',
      }),
    );
    expect(setPosition).toHaveBeenLastCalledWith(
      expect.objectContaining({ country: 'China' }),
    );
  });

  test('keeps the cached country when the fresh request fails', async () => {
    const { options, setPosition, savePosition } = createOptions({
      fetchCountryGeolocation: async () => {
        throw new Error('network');
      },
    });

    await refreshColdStartGeolocation(options);

    expect(setPosition).toHaveBeenCalledTimes(1);
    expect(setPosition).toHaveBeenCalledWith(cachedHongKong);
    expect(savePosition).not.toHaveBeenCalled();
  });

  test('does not replace the cache when the resolved country is unavailable', async () => {
    const unavailableResponse: Geolocation = {
      ...FAKE_GEOLOCATION_RESPONSE,
      results: [
        {
          ...FAKE_GEOLOCATION_RESPONSE.results[0],
          address_components: [
            {
              ...FAKE_GEOLOCATION_RESPONSE.results[0].address_components[0],
              long_name: 'France',
              short_name: 'FR',
            },
          ],
        },
      ],
    };
    const { options, setPosition, savePosition } = createOptions({
      fetchCountryGeolocation: async () => unavailableResponse,
    });

    await refreshColdStartGeolocation(options);

    expect(setPosition).toHaveBeenCalledTimes(1);
    expect(setPosition).toHaveBeenCalledWith(cachedHongKong);
    expect(savePosition).not.toHaveBeenCalled();
  });

  test('keeps the cached country when Android location permission is denied', async () => {
    const { options, fetchCountryGeolocation, savePosition } = createOptions({
      requestAndroidLocationPermission: async () => false,
    });

    await refreshColdStartGeolocation(options);

    expect(fetchCountryGeolocation).not.toHaveBeenCalled();
    expect(savePosition).not.toHaveBeenCalled();
  });

  test('still refreshes on iOS without requesting the Android permission', async () => {
    const { options, requestAndroidLocationPermission, fetchCountryGeolocation } =
      createOptions({
        isAndroid: false,
        getCachedPosition: async () => null,
      });

    await refreshColdStartGeolocation(options);

    expect(requestAndroidLocationPermission).not.toHaveBeenCalled();
    expect(fetchCountryGeolocation).toHaveBeenCalledTimes(1);
  });
});

